/**
 * TC-SURFACES-001 / TC-REG-001 (GH-404 F-7, F-8, AC-F7-1, NFR-4, DM-1,
 * DEC-8) — the `dispatch status` worktree-path golden pair: a lane record
 * carrying the worktree context renders the `worktreePath=` line exactly as
 * the committed golden pins it; a context-less record (pre-change,
 * disable-worktrees — DEC-8) renders byte-identically to the preserved
 * pre-change golden, which is the exception-mode pin (0-byte delta) and is
 * never regenerated by the worktree work.
 */
import { describe, expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { renderDispatchStatusText } from "../../packages/cli/src/output/dispatch-text";
import type { DispatchLaneRecord } from "../../packages/core/src/contracts/index";

const GOAL = join(process.cwd(), "tests/golden");
const readGolden = (name: string): string => readFileSync(join(GOAL, name), "utf8");

const record = (worktreePath?: string): DispatchLaneRecord => ({
  schema: "delivery.dispatch.lane.v1",
  ref: "GH-404",
  repository: "github.com/owner/repo",
  attemptId: "attempt-404",
  sessionId: "session-1",
  harnessKind: "opencode",
  owner: { processId: 4242, startedAt: "2026-11-25T12:00:00.000Z" },
  iterationOrdinal: 1,
  restartsConsumed: 0,
  state: "active",
  recordedAt: "2026-11-25T12:00:00.000Z",
  ...(worktreePath === undefined ? {} : { worktreePath }),
});

const statusFor = (worktreePath?: string): string =>
  renderDispatchStatusText({
    query: "status",
    ref: "GH-404",
    repository: "github.com/owner/repo",
    delivering: true,
    stale: false,
    marker: "inside",
    probe: "alive",
    pid: 4242,
    sessionId: "session-1",
    lane: {
      attemptId: "attempt-404",
      harness: "opencode",
      iterationOrdinal: 1,
      restartsConsumed: 0,
      ownerStartedAt: "2026-11-25T12:00:00.000Z",
      recordedAt: "2026-11-25T12:00:00.000Z",
    },
    ...(worktreePath === undefined ? {} : { worktreePath }),
  });

describe("TC-SURFACES-001 dispatch status shows the lane's worktree path", () => {
  test("a worktree lane renders the worktreePath line byte-identical to its golden", () => {
    const rendered = statusFor("/repos/checkout-GH-404");
    expect(rendered).toBe(readGolden("status-worktree.txt"));
  });
});

describe("TC-REG-001 the exception-mode pins are preserved data", () => {
  test("a context-less lane renders byte-identically to the pre-change golden", () => {
    const rendered = statusFor();
    expect(rendered).toBe(readGolden("status-context-less.txt"));
    // Provenance (review F-14, verified fact): the preserved golden's bytes
    // are the MERGE-BASE (e5ff0512) renderer's output for the same data,
    // generated post-change and cross-checked — it contains no worktree line
    // and is never regenerated by the worktree work.
    expect(readGolden("status-context-less.txt").includes("worktreePath=")).toBe(false);
  });

  test("the with-worktree golden differs from the preserved golden by exactly the worktree line", () => {
    const withLine = readGolden("status-worktree.txt");
    const preserved = readGolden("status-context-less.txt");
    expect(withLine.length - preserved.length).toBe("worktreePath=/repos/checkout-GH-404\n".length);
    expect(preserved).toBe(withLine.replace("worktreePath=/repos/checkout-GH-404\n", ""));
  });
});
